//! 🧭️ Canonical selected and reference paths move original input owners while declaration cursors validate the prepared graph.
use super::*;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits};
use std::mem::size_of;
#[derive(Default)]pub(super)struct Normalize{stage:usize,row:usize,found:Option<usize>,retired:[Option<DslValue>;4],retirement:RetainedCloneClose,closing:bool}
fn error()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Own Part21 retained path normalization is invalid")}
fn path(event:&mut SnapshotEditEvent,from:bool)->Option<&mut String>{match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::RenameKey{path,..}if !from=>Some(path),SnapshotEditEvent::MoveValue{path,from:origin}=>Some(if from{origin}else{path}),_=>None}}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:4*size_of::<DslValue>()+64,depth:1,..Default::default()}}
fn slot<'a>(snapshot:&'a Ifc2x3Snapshot,pointer:&str)->Option<&'a V>{let mut fields=pointer.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){return None;}let row=fields.next()?.parse::<usize>().ok()?;if fields.next()!=Some("entities"){return None;}let part=fields.next()?.parse::<usize>().ok()?;if fields.next()!=Some("arguments"){return None;}let argument=fields.next()?.parse::<usize>().ok()?;let mut value=snapshot.document.instances.get(row)?.entities.get(part)?.1.get(argument)?;let mut depth=0;while let Some(field)=fields.next(){if field!="values"||depth==128{return None;}depth+=1;let index=fields.next()?.parse::<usize>().ok()?;value=match value{V::List(values)|V::Typed{items:values,..}=>values.get(index)?,_=>return None};}Some(value)}
impl Normalize{
 pub(super)fn demands(&self,event:&SnapshotEditEvent)->RetirementDemand{let length=match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::MoveValue{path,..}|SnapshotEditEvent::RenameKey{path,..}=>path.len(),_=>0};RetirementDemand{capacity_bytes:length.saturating_add(64+2*size_of::<(String,DslValue)>()+24),copy_bytes:fixed().copy_bytes.saturating_add(length.saturating_mul(2)),..fixed()}}
 pub(super)fn selected(&mut self,event:&mut SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("details-cancelled").into());}if cx.should_yield(){return Ok(false);}if self.stage==2{return Ok(true);}let Some(pointer)=path(event,self.stage==1)else{self.stage+=1;cx.consume_fuel(1);return Ok(self.stage==2)};if !pointer.starts_with("/ifc-"){self.stage+=1;cx.consume_fuel(1);return Ok(self.stage==2);}if pointer.len()>8192{return Err(error().into());}let end=pointer[1..].find('/').map_or(pointer.len(),|index|index+1);let id=identity::parse_ifc_entity_identity(&pointer[1..end]).ok_or_else(error)?;
 if self.row<snapshot.document.instances.len(){if snapshot.document.instances[self.row].id==id{if self.found.is_some(){return Err(err("IFC2x3 selected identity is duplicated").into());}self.found=Some(self.row);}self.row+=1;cx.consume_fuel(1);return Ok(false);}
 let row=self.found.ok_or_else(||err("IFC2x3 selected identity is missing"))?;let demand=RetirementDemand{copy_bytes:fixed().copy_bytes+2*pointer.len()+64,capacity_bytes:pointer.len()+64,..fixed()};let grant=cx.retained_grant();if !retained_clone_grant_admits(grant,demand){return Ok(false);}let mut next=String::new();next.try_reserve_exact(pointer.len()+64).map_err(|_|err("IFC2x3 selected path allocation failed"))?;use std::fmt::Write;write!(next,"/document/instances/{row}").map_err(|_|error())?;next.push_str(&pointer[end..]);let capacity=next.capacity();self.retired[self.stage]=Some(DslValue::String(std::mem::replace(pointer,next)));self.stage+=1;self.row=0;self.found=None;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);Ok(self.stage==2)}
 pub(super)fn reference(&mut self,event:&mut SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("details-cancelled").into());}if cx.should_yield(){return Ok(false);}let demand=self.demands(event);let grant=cx.retained_grant();if !retained_clone_grant_admits(grant,demand){return Ok(false);}let SnapshotEditEvent::SetValue{path,value}=event else{cx.consume_fuel(1);return Ok(true)};if path.len()>8192{return Err(error().into());}let(parent,field)=path.rsplit_once('/').unwrap_or(("",""));let append=field=="appendReference";let virtual_slot=field=="reference";let payload=field=="value"&&matches!(slot(snapshot,parent),Some(V::Ref(_)));if !append&&!virtual_slot&&!payload{cx.consume_fuel(1);return Ok(true);}if append&&!matches!(slot(snapshot,parent),Some(V::List(_))){return Err(error().into());}if !append&&slot(snapshot,parent).is_none(){return Err(error().into());}let DslValue::String(text)=value else{return Err(err("IFC reference field requires exact decimal text").into())};let next=if virtual_slot&&text.is_empty(){V::Unset}else{V::Ref(parse_id(text)?)};let mut pointer=String::new();pointer.try_reserve_exact(parent.len()+16).map_err(|_|err("IFC2x3 reference path allocation failed"))?;pointer.push_str(parent);if append{pointer.push_str("/values/-");}let capacity=pointer.capacity();self.retired[2]=Some(DslValue::String(std::mem::replace(path,pointer)));let replacement=next.to_value();self.retired[3]=Some(std::mem::replace(value,replacement));if append{let SnapshotEditEvent::SetValue{path,value}=std::mem::replace(event,SnapshotEditEvent::RemoveValue{path:String::new()})else{unreachable!()};*event=SnapshotEditEvent::InsertValue{path,value};}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:capacity+2*size_of::<(String,DslValue)>()+24,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
 pub(super)fn begin_close(&mut self){self.closing=true;}
 pub(super)fn terminal_is_empty(&self)->bool{self.retired.iter().all(Option::is_none)&&self.retirement.is_empty()}
 pub(super)fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.retirement.next_owner_demands::<DslValue>(self.retired.iter().any(Option::is_some),&None,body)}
 pub(super)fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(error());}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}for owner in &mut self.retired{if owner.is_some(){return self.retirement.begin_granted(owner,grant)?.ok_or_else(error);}}Ok(RetainedCloneStep::Complete(Default::default()))}
}
